    If(IsBlank(LookUp(colRg, Status = "Vorlage")),
        Set(varIsLoading, true);
        Set(varPatchFehler, false);
        IfError(Patch(RG_Rundgaenge, Defaults(RG_Rundgaenge), {Title: "Vorlagen (Builder)", Beschreibung: "Vorlagen für den Rundgang-Builder. Wird nie aktiviert.", RgReihenfolge: 99999, Aktiv: false, Status: "Vorlage", Fassung: 0, EntwurfFassung: 1, EntwurfVon: ""}), Set(varPatchFehler, true));
        Refresh(RG_Rundgaenge);
        Set(varVorlageNeu, LookUp(RG_Rundgaenge, Status = "Vorlage"));
        If(!varPatchFehler && !IsBlank(varVorlageNeu.ID),
            With({b: Patch(RG_Bereiche, Defaults(RG_Bereiche), {Title: "Vorlagen", RundgangID: varVorlageNeu.ID, Fassung: 1, RgReihenfolge: 10, Hinweis: "", Aktiv: false, QuelleID: 0})},
                With({k1: Patch(RG_Kategorien, Defaults(RG_Kategorien), {Title: "Sichtprüfung", BereichID: b.ID, RundgangID: varVorlageNeu.ID, Fassung: 1, RgReihenfolge: 10, Hinweis: "", Aktiv: true, QuelleID: 0})},
                With({k2: Patch(RG_Kategorien, Defaults(RG_Kategorien), {Title: "Messwerte", BereichID: b.ID, RundgangID: varVorlageNeu.ID, Fassung: 1, RgReihenfolge: 20, Hinweis: "", Aktiv: true, QuelleID: 0})},
