                ForAll(Table(
                    {K: 1, R: 10, T: "Bereich sauber und ordentlich?", Typ: "IONIO", Pfl: true, Foto: "Bei Mangel Pflicht", Einh: "", Mi: -999999, Ma: -999999, Gm: "Mangel", W: ""},
                    {K: 1, R: 20, T: "Keine Schäden sichtbar?", Typ: "IONIO", Pfl: true, Foto: "Bei Mangel Pflicht", Einh: "", Mi: -999999, Ma: -999999, Gm: "Mangel", W: ""},
                    {K: 1, R: 30, T: "Fluchtweg und Notausgang frei?", Typ: "IONIO", Pfl: true, Foto: "Bei Mangel Pflicht", Einh: "", Mi: -999999, Ma: -999999, Gm: "Mangel", W: ""},
                    {K: 1, R: 40, T: "Zustand", Typ: "AUSWAHL", Pfl: true, Foto: "Aus", Einh: "", Mi: -999999, Ma: -999999, Gm: "Mangel", W: "gut;mäßig;schlecht"},
                    {K: 2, R: 50, T: "Temperatur", Typ: "ZAHL", Pfl: true, Foto: "Aus", Einh: "°C", Mi: 15, Ma: 25, Gm: "Warnen", W: ""},
                    {K: 2, R: 60, T: "Zählerstand", Typ: "ZAHL", Pfl: true, Foto: "Aus", Einh: "", Mi: -999999, Ma: -999999, Gm: "Mangel", W: ""},
                    {K: 2, R: 70, T: "Anzahl im Regal", Typ: "ZAHL", Pfl: true, Foto: "Bei Mangel Pflicht", Einh: "Stück", Mi: 100, Ma: 1000, Gm: "Mangel", W: ""},
                    {K: 3, R: 80, T: "Datum der letzten Wartung", Typ: "DATUM", Pfl: true, Foto: "Aus", Einh: "", Mi: -999999, Ma: -999999, Gm: "Mangel", W: ""},
                    {K: 3, R: 90, T: "Schäden an", Typ: "MEHRFACH", Pfl: false, Foto: "Aus", Einh: "", Mi: -999999, Ma: -999999, Gm: "Mangel", W: "Boden;Wand;Decke;Tür;Fenster"},
                    {K: 3, R: 100, T: "Bemerkung", Typ: "TEXT", Pfl: false, Foto: "Aus", Einh: "", Mi: -999999, Ma: -999999, Gm: "Mangel", W: ""}
                ) As v,
                    Patch(RG_Pruefpunkte, Defaults(RG_Pruefpunkte), {Title: v.T, KategorieID: Switch(v.K, 1, k1.ID, 2, k2.ID, k3.ID), RundgangID: varVorlageNeu.ID, Fassung: 1, RgReihenfolge: v.R, Aktiv: true, QuelleID: 0, Eingabetyp: {Value: v.Typ}, Pflicht: v.Pfl, Auswahlwerte: v.W, Einheit: v.Einh, MinWert: If(v.Mi = -999999, Blank(), v.Mi), MaxWert: If(v.Ma = -999999, Blank(), v.Ma), Hinweis: "", FotoMoeglich: false, Foto: {Value: v.Foto}, KommentarPflicht: false, Grenzmodus: {Value: v.Gm}, BedingungPunkt: 0, BedingungWert: "", HinweisBildID: 0})
                ))))
