props.btnLiBearbeiten.OnSelect:
If(!varIsLoading && Now() >= varSperreBis,
    Set(varSperreBis, DateAdd(Now(), 1, TimeUnit.Seconds));
    If(fnStatus(ThisItem.Status, ThisItem.Aktiv) = "Entwurf" || Coalesce(ThisItem.EntwurfFassung, 0) > 0,
        Set(varFrage, "");
        Set(varRgID, ThisItem.ID);
        Set(varFassung, Coalesce(ThisItem.EntwurfFassung, 1));
        Set(varSchreibbar, true);
        Set(varJob, "laden");
        Set(varArbeitStart, false);
        Set(varIsLoading, true);
        Set(varLadeText, "");
        Navigate(scrEditor, ScreenTransition.None),
        varFrage <> "fassung" & ThisItem.ID,
        Set(varFrage, "fassung" & ThisItem.ID),
        Set(varFrage, "");
        Set(varRgID, ThisItem.ID);
        Set(varFassung, 0);
        Set(varSchreibbar, true);
        Set(varNach, "neueFassung");
        Set(varJob, If(Coalesce(ThisItem.Fassung, 0) = 0, "vorbereiten", "neueFassung"));
        Set(varArbeitStart, false);
        Set(varIsLoading, true);
        Set(varLadeText, "");
