props.btnLiAktion.OnSelect:
If(!varIsLoading && Now() >= varSperreBis,
    If(varFrage <> "aktion" & ThisItem.ID,
        Set(varFrage, "aktion" & ThisItem.ID);
        Set(varSperreBis, DateAdd(Now(), 1, TimeUnit.Seconds));
        If(fnStatus(ThisItem.Status, ThisItem.Aktiv) = "Aktiv",
            With({d: LookUp(RG_Durchfuehrungen, Title = "R" & ThisItem.ID & "-" & Text(Today(), "yyyy-mm-dd"))}, Set(varHeuteLaeuft, !IsBlank(d) && d.Status <> "Abgeschlossen"))
        ),
        Set(varFrage, "");
        Set(varIsLoading, true);
        Set(varPatchFehler, false);
        If(fnStatus(ThisItem.Status, ThisItem.Aktiv) = "Aktiv",
            IfError(Patch(RG_Rundgaenge, LookUp(RG_Rundgaenge, ID = ThisItem.ID), {Status: "Archiviert", Aktiv: false}), Set(varPatchFehler, true)),
            fnStatus(ThisItem.Status, ThisItem.Aktiv) = "Archiviert",
            IfError(Patch(RG_Rundgaenge, LookUp(RG_Rundgaenge, ID = ThisItem.ID), {Status: "Aktiv", Aktiv: true, Fassung: fnAktiveFassung(ThisItem.Fassung)}), Set(varPatchFehler, true)),
            fnStatus(ThisItem.Status, ThisItem.Aktiv) = "Entwurf" && Coalesce(LookUp(RG_Rundgaenge, ID = ThisItem.ID).Fassung, 0) = 0 && !Coalesce(LookUp(RG_Rundgaenge, ID = ThisItem.ID).Aktiv, false),
            IfError(Remove(RG_Pruefpunkte, Filter(RG_Pruefpunkte, RundgangID = ThisItem.ID)), Set(varPatchFehler, true));
            IfError(Remove(RG_Kategorien, Filter(RG_Kategorien, RundgangID = ThisItem.ID)), Set(varPatchFehler, true));
            IfError(Remove(RG_Bereiche, Filter(RG_Bereiche, RundgangID = ThisItem.ID)), Set(varPatchFehler, true));
            IfError(Remove(RG_Plan, Filter(RG_Plan, RundgangID = ThisItem.ID)), Set(varPatchFehler, true));
            If(!varPatchFehler, IfError(Remove(RG_Rundgaenge, LookUp(RG_Rundgaenge, ID = ThisItem.ID)), Set(varPatchFehler, true)))
        );
        If(varPatchFehler, Notify("Das hat nicht geklappt. Bitte erneut versuchen.", NotificationType.Error), Notify("Erledigt.", NotificationType.Success));
        Set(varIsLoading, true);
        Concurrent(Refresh(RG_Rundgaenge), Refresh(RG_Plan));
        Concurrent(ClearCollect(colRg, RG_Rundgaenge), ClearCollect(colPlanAlle, RG_Plan));
        Set(varIsLoading, false)
    )
)

props.btnLiVerwerfen.OnSelect:
If(!varIsLoading && Now() >= varSperreBis,
    If(varFrage <> "verwerfen" & ThisItem.ID,
        Set(varFrage, "verwerfen" & ThisItem.ID);
        Set(varSperreBis, DateAdd(Now(), 1, TimeUnit.Seconds)),
        Set(varFrage, "");
        Set(varIsLoading, true);
        Set(varPatchFehler, false);
        With({f: Coalesce(LookUp(RG_Rundgaenge, ID = ThisItem.ID).EntwurfFassung, 0)},
            If(f > 0 && f <> fnAktiveFassung(ThisItem.Fassung),
                IfError(Remove(RG_Pruefpunkte, Filter(RG_Pruefpunkte, RundgangID = ThisItem.ID && Fassung = f)), Set(varPatchFehler, true));
                IfError(Remove(RG_Kategorien, Filter(RG_Kategorien, RundgangID = ThisItem.ID && Fassung = f)), Set(varPatchFehler, true));
                IfError(Remove(RG_Bereiche, Filter(RG_Bereiche, RundgangID = ThisItem.ID && Fassung = f)), Set(varPatchFehler, true))
            )
        );
        If(!varPatchFehler, IfError(Patch(RG_Rundgaenge, LookUp(RG_Rundgaenge, ID = ThisItem.ID), {EntwurfFassung: 0, EntwurfVon: ""}), Set(varPatchFehler, true)));
        If(varPatchFehler, Notify("Verwerfen unvollständig. Bitte erneut versuchen.", NotificationType.Error), Notify("Entwurf verworfen.", NotificationType.Success));
        Set(varIsLoading, true);
        Concurrent(Refresh(RG_Rundgaenge), Refresh(RG_Plan));
        Concurrent(ClearCollect(colRg, RG_Rundgaenge), ClearCollect(colPlanAlle, RG_Plan));
        Set(varIsLoading, false)
    )
)

props.btnNeuAnlegen.OnSelect:
If(!varIsLoading && Now() >= varSperreBis,
    Set(varSperreBis, DateAdd(Now(), 1, TimeUnit.Seconds));
    If(Trim(txtNeuName.Text) = "",
        Notify("Bitte einen Namen eingeben.", NotificationType.Warning),
        !IsBlank(LookUp(colRg, Lower(Trim(Title)) = Lower(Trim(txtNeuName.Text)))),
        Notify("Diesen Namen gibt es schon.", NotificationType.Warning),
        !varNeuLeer && IsBlank(ddNeuQuelle.Selected),
        Notify("Bitte den Rundgang wählen, der kopiert werden soll.", NotificationType.Warning),
        Set(varIsLoading, true);
        Set(varPatchFehler, false);
        IfError(Patch(RG_Rundgaenge, Defaults(RG_Rundgaenge), {Title: Left(Trim(txtNeuName.Text), 255), Beschreibung: "", RgReihenfolge: Coalesce(Max(colRg, RgReihenfolge), 0) + 10, Aktiv: false, Status: "Entwurf", Fassung: 0, EntwurfFassung: 1, EntwurfVon: User().FullName}), Set(varPatchFehler, true));
        Refresh(RG_Rundgaenge);
        Set(varNeuRg, First(Sort(Filter(RG_Rundgaenge, Title = Left(Trim(txtNeuName.Text), 255)), ID, SortOrder.Descending)));
        If(varPatchFehler || IsBlank(varNeuRg.ID),
            Set(varIsLoading, false);
            Notify("Anlegen fehlgeschlagen. Bitte erneut versuchen.", NotificationType.Error),
            Set(varNeuOffen, false);
            Set(varRgID, varNeuRg.ID);
            Set(varFassung, 1);
            Set(varSchreibbar, true);
            If(varNeuLeer,
                Set(varJob, "laden"),
                With({s: ddNeuQuelle.Selected},
                    Set(varQuelleR, s.ID);
                    Set(varQuelleF, If(fnStatus(s.Status, s.Aktiv) = "Entwurf", Coalesce(s.EntwurfFassung, 1), fnAktiveFassung(s.Fassung)));
                    Set(varQuelleNurAktiv, fnStatus(s.Status, s.Aktiv) <> "Entwurf")
                );
                Set(varZielR, varNeuRg.ID);
                Set(varZielF, 1);
                Set(varJob, "quelle")
            );
            Reset(txtNeuName);
            Set(varArbeitStart, false);
            Set(varIsLoading, true);
            Set(varLadeText, "");
            Navigate(scrEditor, ScreenTransition.None)
        )
    )
)

props.scrEditor.OnVisible:
Set(varAktivOffen, false);
Set(varHolenOffen, false);
Set(varMehrereOffen, false);
Set(varBildOffen, false);
If(varJob <> "", Set(varIsLoading, true); Set(varArbeitStart, true))

props.txtEdName.OnChange:
If(varSchreibbar && Trim(Self.Text) <> "" && Self.Text <> varRg.Title,
    If(!IsBlank(LookUp(colRg, ID <> varRgID && Lower(Trim(Title)) = Lower(Trim(Self.Text)))),
        Notify("Diesen Namen gibt es schon.", NotificationType.Warning);
        Reset(txtEdName),
        Set(varPatchFehler, false);
        IfError(Patch(RG_Rundgaenge, LookUp(RG_Rundgaenge, ID = varRgID), {Title: Left(Trim(Self.Text), 255)}), Set(varPatchFehler, true));
        If(varPatchFehler, Notify("Name nicht gespeichert.", NotificationType.Error), Set(varRg, LookUp(RG_Rundgaenge, ID = varRgID)); Set(varGespeichertText, "Name gespeichert " & Text(Now(), "hh:mm:ss")))
    ),
    Trim(Self.Text) = "",
    Reset(txtEdName)
)

props.btnEdAktivieren.OnSelect:
If(!varIsLoading && Now() >= varSperreBis,
    If(CountRows(Filter(galPr.AllItems, Art = "Fehler")) > 0,
        Notify("Erst die " & CountRows(Filter(galPr.AllItems, Art = "Fehler")) & " Fehler beheben (rechts unten, rot).", NotificationType.Warning),
        Set(varIsLoading, true);
        With({fa: If(fnStatus(varRg.Status, varRg.Aktiv) = "Entwurf", 0, fnAktiveFassung(varRg.Fassung))},
            ClearCollect(colAltP, Filter(RG_Pruefpunkte, RundgangID = varRgID && Fassung = fa))
        );
        RemoveIf(colAltP, !Coalesce(Aktiv, false));
        With({d: LookUp(RG_Durchfuehrungen, Title = "R" & varRgID & "-" & Text(Today(), "yyyy-mm-dd"))}, Set(varHeuteLaeuft, !IsBlank(d) && d.Status <> "Abgeschlossen"));
        Set(varIsLoading, false);
        Set(varAktivOffen, true)
    )
)

props.btnEdBearbeiten.OnSelect:
If(!varIsLoading && Now() >= varSperreBis,
    Set(varSperreBis, DateAdd(Now(), 1, TimeUnit.Seconds));
    Set(varSchreibbar, true);
    Set(varJob, "neueFassung");
    Set(varIsLoading, true);
    Set(varArbeitStart, true)
)

props.galGl.Items:
Sort(
    Ungroup(
