            Reset(txtKName);
            Reset(ddKBereich);
            Reset(txtPFrage);
            Reset(txtPEinheit);
            Reset(txtPMin);
            Reset(txtPMax);
            Reset(txtPWerte);
            Reset(txtPHinweis);
            Reset(ddPKategorie);
            Reset(ddPBedA);
            Reset(ddPBedW),
            Set(varAuswahlEbene, 1);
            Set(varAuswahlID, b1.ID);
            Set(varCtxB, b1.ID);
            Set(varCtxK, 0);
            Set(varFrage, "");
            Reset(txtBName);
            Reset(txtKName);
            Reset(ddKBereich);
            Reset(txtPFrage);
            Reset(txtPEinheit);
            Reset(txtPMin);
            Reset(txtPMax);
            Reset(txtPWerte);
            Reset(txtPHinweis);
            Reset(ddPKategorie);
            Reset(ddPBedA);
            Reset(ddPBedW)
        )
    );
    Set(varJob, "")
);
If(varJob = "auswahl",
